          "content": "package fruit.model;\n\n/**\n * Model class representing a Fruit product.\n */\npublic class Fruit {\n\n    private int fruitId;\n    private String fruitName;\n    private double price;\n    private int quantity;\n    private String origin;\n\n    /**\n     * Default constructor.\n     */\n    public Fruit() {\n    }\n\n    /**\n     * Parameterized constructor.\n     *\n     * @param fruitId unique id of the fruit\n     * @param fruitName name of the fruit\n     * @param price price per item\n     * @param quantity available stock quantity\n     * @param origin origin country\n     */\n    public Fruit(int fruitId, String fruitName, double price, int quantity, String origin) {\n        this.fruitId = fruitId;\n        this.fruitName = fruitName;\n        this.price = price;\n        this.quantity = quantity;\n        this.origin = origin;\n    }\n\n    /**\n     * Gets fruit id.\n     *\n     * @return fruitId\n     */\n    public int getFruitId() {\n        return fruitId;\n    }\n\n    /**\n     * Sets fruit id.\n     *\n     * @param fruitId fruitId\n     */\n    public void setFruitId(int fruitId) {\n        this.fruitId = fruitId;\n    }\n\n    /**\n     * Gets fruit name.\n     *\n     * @return fruitName\n     */\n    public String getFruitName() {\n        return fruitName;\n    }\n\n    /**\n     * Sets fruit name.\n     *\n     * @param fruitName fruitName\n     */\n    public void setFruitName(String fruitName) {\n        this.fruitName = fruitName;\n    }\n\n    /**\n     * Gets price.\n     *\n     * @return price\n     */\n    public double getPrice() {\n        return price;\n    }\n\n    /**\n     * Sets price.\n     *\n     * @param price price\n     */\n    public void setPrice(double price) {\n        this.price = price;\n    }\n\n    /**\n     * Gets stock quantity.\n     *\n     * @return quantity\n     */\n    public int getQuantity() {\n        return quantity;\n    }\n\n    /**\n     * Sets stock quantity.\n     *\n     * @param quantity quantity\n     */\n    public void setQuantity(int quantity) {\n        this.quantity = quantity;\n    }\n\n    /**\n     * Gets origin.\n     *\n     * @return origin\n     */\n    public String getOrigin() {\n        return origin;\n    }\n\n    /**\n     * Sets origin.\n     *\n     * @param origin origin\n     */\n    public void setOrigin(String origin) {\n        this.origin = origin;\n    }\n\n    @Override\n    public String toString() {\n        return \"Fruit{\"\n                + \"fruitId=\" + fruitId\n                + \", fruitName='\" + fruitName + '\\''\n                + \", price=\" + price\n                + \", quantity=\" + quantity\n                + \", origin='\" + origin + '\\''\n                + '}';\n    }\n}\n",
