          "content": "package worker.model;\n\n/**\n * Model class representing a Worker.\n */\npublic class Worker {\n\n    private String id;\n    private String name;\n    private int age;\n    private double salary;\n    private String workLocation;\n\n    /**\n     * Default constructor.\n     */\n    public Worker() {\n    }\n\n    /**\n     * Parameterized constructor.\n     *\n     * @param id worker id / code\n     * @param name worker name\n     * @param age worker age (18 - 50)\n     * @param salary monthly salary (> 0)\n     * @param workLocation workplace location\n     */\n    public Worker(String id, String name, int age, double salary, String workLocation) {\n        this.id = id;\n        this.name = name;\n        this.age = age;\n        this.salary = salary;\n        this.workLocation = workLocation;\n    }\n\n    /**\n     * Gets worker id/code.\n     *\n     * @return id\n     */\n    public String getId() {\n        return id;\n    }\n\n    /**\n     * Sets worker id/code.\n     *\n     * @param id worker id\n     */\n    public void setId(String id) {\n        this.id = id;\n    }\n\n    /**\n     * Gets worker name.\n     *\n     * @return name\n     */\n    public String getName() {\n        return name;\n    }\n\n    /**\n     * Sets worker name.\n     *\n     * @param name worker name\n     */\n    public void setName(String name) {\n        this.name = name;\n    }\n\n    /**\n     * Gets worker age.\n     *\n     * @return age\n     */\n    public int getAge() {\n        return age;\n    }\n\n    /**\n     * Sets worker age.\n     *\n     * @param age age (18 - 50)\n     */\n    public void setAge(int age) {\n        this.age = age;\n    }\n\n    /**\n     * Gets worker current salary.\n     *\n     * @return salary\n     */\n    public double getSalary() {\n        return salary;\n    }\n\n    /**\n     * Sets worker salary.\n     *\n     * @param salary salary (> 0)\n     */\n    public void setSalary(double salary) {\n        this.salary = salary;\n    }\n\n    /**\n     * Gets work location.\n     *\n     * @return workLocation\n     */\n    public String getWorkLocation() {\n        return workLocation;\n    }\n\n    /**\n     * Sets work location.\n     *\n     * @param workLocation work location\n     */\n    public void setWorkLocation(String workLocation) {\n        this.workLocation = workLocation;\n    }\n}\n",
          "size": 2243
