          "content": "package task.model;\n\n/**\n * Task model representing a work task in the CCRM project.\n */\npublic class Task {\n    private int id;\n    private int taskTypeId;\n    private String requirementName;\n    private String date;\n    private double planFrom;\n    private double planTo;\n    private String assignee;\n    private String reviewer;\n\n    public Task() {\n    }\n\n    public Task(int id, int taskTypeId, String requirementName, String date, double planFrom, double planTo, String assignee, String reviewer) {\n        this.id = id;\n        this.taskTypeId = taskTypeId;\n        this.requirementName = requirementName;\n        this.date = date;\n        this.planFrom = planFrom;\n        this.planTo = planTo;\n        this.assignee = assignee;\n        this.reviewer = reviewer;\n    }\n\n    public int getId() {\n        return id;\n    }\n\n    public void setId(int id) {\n        this.id = id;\n    }\n\n    public int getTaskTypeId() {\n        return taskTypeId;\n    }\n\n    public void setTaskTypeId(int taskTypeId) {\n        this.taskTypeId = taskTypeId;\n    }\n\n    public String getRequirementName() {\n        return requirementName;\n    }\n\n    public void setRequirementName(String requirementName) {\n        this.requirementName = requirementName;\n    }\n\n    public String getDate() {\n        return date;\n    }\n\n    public void setDate(String date) {\n        this.date = date;\n    }\n\n    public double getPlanFrom() {\n        return planFrom;\n    }\n\n    public void setPlanFrom(double planFrom) {\n        this.planFrom = planFrom;\n    }\n\n    public double getPlanTo() {\n        return planTo;\n    }\n\n    public void setPlanTo(double planTo) {\n        this.planTo = planTo;\n    }\n\n    public String getAssignee() {\n        return assignee;\n    }\n\n    public void setAssignee(String assignee) {\n        this.assignee = assignee;\n    }\n\n    public String getReviewer() {\n        return reviewer;\n    }\n\n    public void setReviewer(String reviewer) {\n        this.reviewer = reviewer;\n    }\n\n    /**\n     * Resolves task type ID to its display name.\n     * 1: Code, 2: Test, 3: Design, 4: Review\n     *\n     * @return display name of task type\n     */\n    public String getTaskTypeName() {\n        switch (taskTypeId) {\n            case 1:\n                return \"Code\";\n            case 2:\n                return \"Test\";\n            case 3:\n                return \"Design\";\n            case 4:\n                return \"Review\";\n            default:\n                return \"Unknown\";\n        }\n    }\n}\n",
