                "content": "package feastorder.model;\n\n/**\n * Model class representing a Set Menu entity loaded from CSV.\n */\npublic class FeastMenu {\n\n    private String code;\n    private String name;\n    private double price;\n    private String ingredients;\n\n    public FeastMenu() {\n    }\n\n    public FeastMenu(String code, String name, double price, String ingredients) {\n        this.code = code;\n        this.name = name;\n        this.price = price;\n        this.ingredients = ingredients;\n    }\n\n    public String getCode() {\n        return code;\n    }\n\n    public void setCode(String code) {\n        this.code = code;\n    }\n\n    public String getName() {\n        return name;\n    }\n\n    public void setName(String name) {\n        this.name = name;\n    }\n\n    public double getPrice() {\n        return price;\n    }\n\n    public void setPrice(double price) {\n        this.price = price;\n    }\n\n    public String getIngredients() {\n        return ingredients;\n    }\n\n    public void setIngredients(String ingredients) {\n        this.ingredients = ingredients;\n    }\n\n    /**\n     * Returns ingredients formatted with '+ ' per line.\n     *\n     * @return formatted ingredients string\n     */\n    public String getFormattedIngredients() {\n        if (ingredients == null || ingredients.isEmpty()) {\n            return \"\";\n        }\n        String[] parts = ingredients.split(\"#\");\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < parts.length; i++) {\n            sb.append(\"+ \").append(parts[i].trim());\n            if (i < parts.length - 1) {\n                sb.append(\"\\n\");\n            }\n        }\n        return sb.toString();\n    }\n}\n",
