                "content": "package studentcourse.model;\n\n/**\n * Model class representing a Student entity.\n * Only manages data, state, constructor, and getter/setter methods.\n */\npublic class Student {\n\n    private String studentId;\n    private String fullName;\n    private String major;\n    private double gpa;\n\n    /**\n     * Default constructor.\n     */\n    public Student() {\n    }\n\n    /**\n     * Parameterized constructor.\n     *\n     * @param studentId student ID (STU0000)\n     * @param fullName  student full name\n     * @param major     student major\n     * @param gpa       student GPA (0.0 - 4.0)\n     */\n    public Student(String studentId, String fullName, String major, double gpa) {\n        this.studentId = studentId;\n        this.fullName = fullName;\n        this.major = major;\n        this.gpa = gpa;\n    }\n\n    /**\n     * Gets student ID.\n     *\n     * @return student ID\n     */\n    public String getStudentId() {\n        return studentId;\n    }\n\n    /**\n     * Sets student ID.\n     *\n     * @param studentId student ID\n     */\n    public void setStudentId(String studentId) {\n        this.studentId = studentId;\n    }\n\n    /**\n     * Gets student full name.\n     *\n     * @return full name\n     */\n    public String getFullName() {\n        return fullName;\n    }\n\n    /**\n     * Sets student full name.\n     *\n     * @param fullName full name\n     */\n    public void setFullName(String fullName) {\n        this.fullName = fullName;\n    }\n\n    /**\n     * Gets student major.\n     *\n     * @return major\n     */\n    public String getMajor() {\n        return major;\n    }\n\n    /**\n     * Sets student major.\n     *\n     * @param major major\n     */\n    public void setMajor(String major) {\n        this.major = major;\n    }\n\n    /**\n     * Gets student GPA.\n     *\n     * @return GPA\n     */\n    public double getGpa() {\n        return gpa;\n    }\n\n    /**\n     * Sets student GPA.\n     *\n     * @param gpa GPA\n     */\n    public void setGpa(double gpa) {\n        this.gpa = gpa;\n    }\n\n    @Override\n    public String toString() {\n        return String.format(\"%s, %s, %s, %.1f\", studentId, fullName, major, gpa);\n    }\n}\n",
